def longestSubstring(s, k):
    if len(s) < k:
        return 0

    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    chars_below_k = [char for char in char_count if char_count[char] < k]

    if not chars_below_k:
        return len(s)

    substrings = []
    start = 0
    for i in range(len(s)):
        if s[i] in chars_below_k:
            if i > start:
                substrings.append(s[start:i])
            start = i + 1
    if start < len(s):
        substrings.append(s[start:])

    max_length = 0
    for substring in substrings:
        max_length = max(max_length, longestSubstring(substring, k))

    return max_length

# Example usage:
